import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.LongAdder;

public class Main {
    public static void main(String[] args) throws Exception {
        int threads = 8;
        int rounds = 20_000;
        int expected = threads * rounds;

        Map<String, Integer> nonAtomic = new ConcurrentHashMap<>();
        nonAtomic.put("hits", 0);
        runWorkers(threads, () -> {
            for (int i = 0; i < rounds; i++) {
                Integer old = nonAtomic.get("hits");
                nonAtomic.put("hits", old + 1);
            }
        });
        System.out.println("get+put result = " + nonAtomic.get("hits") + " / expected = " + expected);

        ConcurrentHashMap<String, LongAdder> counters = new ConcurrentHashMap<>();
        runWorkers(threads, () -> {
            for (int i = 0; i < rounds; i++) {
                counters.computeIfAbsent("hits", key -> new LongAdder()).increment();
            }
        });
        long safe = counters.get("hits").sum();
        System.out.println("LongAdder result = " + safe + " / expected = " + expected);
        assert safe == expected;

        ConcurrentHashMap<String, String> nullCheck = new ConcurrentHashMap<>();
        try {
            nullCheck.put("k", null);
            throw new AssertionError("ConcurrentHashMap accepted null value");
        } catch (NullPointerException expectedException) {
            System.out.println("null value rejected");
        }

        ConcurrentHashMap<Integer, Integer> iterating = new ConcurrentHashMap<>();
        for (int i = 0; i < 4; i++) {
            iterating.put(i, i);
        }
        int visited = 0;
        for (Integer key : iterating.keySet()) {
            visited++;
            if (key < 4) {
                iterating.put(100 + key, key);
            }
        }
        System.out.println("weak iteration visited=" + visited + ", finalSize=" + iterating.size());
    }

    private static void runWorkers(int threads, Runnable task) throws InterruptedException {
        CountDownLatch done = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                try {
                    task.run();
                } finally {
                    done.countDown();
                }
            }, "worker-" + i).start();
        }
        done.await();
    }
}
